mapper.select:
SELECT PP.PORTFOLIO_ID, PP.PORTFOLIO_NAME, PP.VDATE, PP.MDATE FROM PTL_PORTFOLIO PP INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId,jdbcType=VARCHAR}
AND (PP.PORTFOLIO_ID IN
#{portfolio}
or PP.PARENT_PORTFOLIO_ID IN
#{portfolio}
)
AND PP.MDATE >=to_date(#{mDateBegin},'yyyy-MM-dd')
AND PP.MDATE <=to_date(#{mDateEnd},'yyyy-MM-dd')
ORDER BY PP.MDATE DESC

WITH EXERCISE_PLAN_TEMP AS ( SELECT FINPROD_ID,min(EXERCISE_DATE) EXERCISE_DATE FROM FIN_EXERCISE_PLAN WHERE EXERCISE_DATE > DATE '${valDate}' GROUP BY FINPROD_ID ), BUY_CPRICE_TEMP AS ( SELECT A.FINPROD_ID, sum(nvl(A.UNIT_CPRICE,0)*nvl(A.SHARE_AMT,A.PRIN_AMT))/SUM(nvl(A.SHARE_AMT,A.PRIN_AMT)) AS BUY_COST from TRD_PRODUCT_DEAL A inner join TRD_PRODUCT_DEAL_ADD C on A.TRADE_ID=C.TRADE_ID and A.TRADE_STATUS =#{TRADE_STATUS_01} and NVL(A.IS_CANCEL,'N') ='N' where A.FINPROD_TYPE2 =#{finprodType,jdbcType=VARCHAR} AND A.PS =#{PS_T01} and A.TRADE_DATE <= DATE'${valDate}' AND PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR} GROUP BY A.FINPROD_ID ), PTL_SEC_ACCT_TEMP AS ( SELECT DISTINCT A.PORTFOLIO_ID , listagg (nvl(B.BROKER_NAME, B.SEC_ACCT_NAME), ',') WITHIN GROUP (ORDER BY nvl(B.BROKER_NAME, B.SEC_ACCT_NAME)) ACCT_NAME FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID WHERE A.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR} GROUP BY A.PORTFOLIO_ID ), PTL_CAPACCT_INFO_TEMP AS ( SELECT DISTINCT A.PORTFOLIO_ID , B.ACCT_NAME FROM PTL_CAPACCT_INFO A INNER JOIN STL_CAPACCT_INFO B ON A.ACCT_NO = B.ACCT_NO AND A.ACCT_TYPE =#{ACCT_TYPE_A01} WHERE A.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR} ), RATE_TEMP AS ( SELECT T1.FINPROD_ID,nvl(T8.YIELD, T6.RATE)* 100 RATE FROM FIN_PRODUCT T1 LEFT JOIN FIN_CASH_INFO T5 ON T5.FINPROD_ID = T1.FINPROD_ID AND T5.CASH_TYPE_2 = #{CASH_TYPE_C02} AND T5.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE_01} LEFT JOIN FIN_RATE_INFO T6 ON T6.CASH_ID = T5.CASH_ID AND T6.EFF_DATE = T1.VDATE LEFT JOIN ( SELECT FINPROD_ID,YIELD,CASH_ID FROM ( SELECT FINPROD_ID,YIELD,CASH_ID,RANK() OVER(PARTITION BY FINPROD_ID ORDER BY EFF_DATE DESC) rowno FROM FIN_CASH_CALC_RULE T8 ) WHERE rowno=1 ) T8 ON T8.CASH_ID = T5.CASH_ID AND T8.FINPROD_ID = T1.FINPROD_ID WHERE T1.FINPROD_TYPE2 =#{finprodType,jdbcType=VARCHAR} ), BOND_VALUATION_TEMP AS( SELECT SEC_ID,VALUE_SOURCE,M_DURATION,VALUE_DATE FROM ( SELECT SEC_ID,VALUE_SOURCE,M_DURATION,VALUE_DATE,RANK() OVER(PARTITION BY SEC_ID ,VALUE_SOURCE ORDER BY VALUE_DATE DESC ) AS rowno FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=DATE'${valDate}' ) WHERE rowno=1 ) SELECT PSP.FINPROD_ID finprodId, FP.FINPROD_ABBR finprodAbbr, BCT.BUY_COST buyCost, FP.VDATE , FP.MDATE , EPT.EXERCISE_DATE exerciseDate, FP.TRADE_MARKET tradeMarket, FPT.TYPE_6 TYPE6, DECODE(FP.TRADE_MARKET,#{TRADE_PLACE_01},PCT.ACCT_NAME,PAT.ACCT_NAME) acctName , RT.RATE , PSP.AMOUNT FROM ( SELECT PORTFOLIO_ID, FINPROD_ID, NVL(SUM(AMOUNT),0)*100 AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR} AND CDATE = DATE'${valDate}' AND HODING_TYPE IN ${POSITION_TYPE_030506} GROUP BY PORTFOLIO_ID, FINPROD_ID ) PSP INNER JOIN FIN_PRODUCT FP ON PSP.FINPROD_ID=FP.FINPROD_ID AND FP.FINPROD_TYPE2 =#{finprodType,jdbcType=VARCHAR} INNER JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID=FP.FINPROD_ID AND FPT.BRANCH=0 LEFT JOIN EXERCISE_PLAN_TEMP EPT ON PSP.FINPROD_ID=EPT.FINPROD_ID LEFT JOIN BUY_CPRICE_TEMP BCT ON PSP.FINPROD_ID=BCT.FINPROD_ID LEFT JOIN PTL_SEC_ACCT_TEMP PAT ON PSP.PORTFOLIO_ID=PAT.PORTFOLIO_ID LEFT JOIN PTL_CAPACCT_INFO_TEMP PCT ON PSP.PORTFOLIO_ID=PCT.PORTFOLIO_ID LEFT JOIN RATE_TEMP RT ON PSP.FINPROD_ID=RT.FINPROD_ID LEFT JOIN BOND_VALUATION_TEMP BVT ON FP.FINPROD_MARKET_ID = BVT.SEC_ID AND decode(FP.TRADE_MARKET,#{TRADE_PLACE_03},#{VALUATION_SOURCE_CSD},#{TRADE_PLACE_04},#{VALUATION_SOURCE_CSD},#{VALUATION_SOURCE_CBC}) = BVT.VALUE_SOURCE
AND FP.ISSUE_TYPE = #{issueType,jdbcType=VARCHAR}
AND BVT.M_DURATION >=#{durationStart,jdbcType=DECIMAL}
AND BVT.M_DURATION <=#{durationEnd,jdbcType=DECIMAL}
AND RT.RATE >=#{yieldStart,jdbcType=DECIMAL}
AND RT.RATE <=#{yieldEnd,jdbcType=DECIMAL}
